RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration -- multiline::replacement

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('crates/printer/src/util.rs')
text = path.read_text()
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if is_multi_line && m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            // Look-ahead bytes are available to the matcher, but must not be
            // included in the replacement output.
            let end = range.end.min(subject.len());
            if last_match < end {
                dst.extend_from_slice(&subject[last_match..end]);
            }
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))
path = Path('CHANGELOG.md')
text = path.read_text()
old = 'Bug fixes:\n\n'
new = '''Bug fixes:

* Fix multiline replacement output including non-matching lines or duplicating
  later matches.
'''
assert old in text
path.write_text(text.replace(old, new, 1))
